using System;using System.IO;using System.Collections.Generic;
// Only current CN70 fields: this module does not copy US60/DNF86 transport layouts.
class Offline70EconomyProtocol {
 internal static ushort SkillBookSlot(byte[] cipher,byte[] keys){if(cipher==null||cipher.Length!=16)throw new InvalidDataException("Skill book request block");byte[] b=Offline70RoleProtocol.BatchCryptFG(cipher,keys,4,false);for(int i=2;i<b.Length;i++)if(b[i]!=0)throw new InvalidDataException("Skill book request padding");ushort slot=BitConverter.ToUInt16(b,0);if(!(slot>=3&&slot<9||slot>=57&&slot<89))throw new InvalidDataException("Skill book inventory slot");return slot;}
 internal static byte[] SkillBookReply(ushort slot,ushort amount,bool success,byte[] keys){byte[] b;if(success){b=new byte[12];b[0]=1;BitConverter.GetBytes(slot).CopyTo(b,1);/* type0 increases native SP */BitConverter.GetBytes((uint)amount).CopyTo(b,4);}else b=new byte[]{0,0x17};return Offline70RoleProtocol.BatchPacketFG(1,32,b,keys,true);}
 internal static byte[] CashBalanceBody(uint cash,uint boundCash){if(cash>Offline70Economy.WalletLimit||boundCash>Offline70Economy.WalletLimit)throw new InvalidDataException("Offline cash bounds");byte[] b=new byte[9];b[0]=1;BitConverter.GetBytes(cash).CopyTo(b,1);BitConverter.GetBytes(boundCash).CopyTo(b,5);return b;}
 internal static byte[] CashBalanceReply(Offline70EconomyState s,byte[] keys){Offline70Economy.Validate(s);return Offline70RoleProtocol.Packet(0,53,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(CashBalanceBody(s.OfflineCash,s.BoundCash),8),keys,11,true));}
 internal static Offline70EconomyUseRequest ParseUse(byte[] cipher,byte[] keys){if(cipher==null||cipher.Length!=16)throw new InvalidDataException("Use47 cipher bounds");byte[] b=Offline70RoleProtocol.Xtea(cipher,keys,false);if(b[2]!=0)throw new InvalidDataException("Only ordinary inventory item use is supported");return new Offline70EconomyUseRequest{Slot=BitConverter.ToUInt16(b,0),List=b[2],InstanceChecksum=BitConverter.ToUInt32(b,3),ItemId=BitConverter.ToUInt32(b,7),Tick=BitConverter.ToUInt32(b,11)};}
 internal static byte[] UseBody(Offline70EconomyUseRequest r,bool success,byte error){if(r==null)throw new InvalidDataException("Use reply context");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)(success?1:0));if(success)w.Write(r.Slot);else w.Write(error);w.Write(r.List);w.Write(r.InstanceChecksum);w.Write(r.ItemId);return m.ToArray();}}
 internal static byte[] UseReply(Offline70EconomyUseRequest r,bool success,byte[] keys){return Offline70RoleProtocol.Packet(1,47,Offline70RoleProtocol.Xtea(Offline70GoldLoot.Pad(Offline70RoleProtocol.WithDungeonIntegrity(UseBody(r,success,0x17)),8),keys,true));}
 // Actual CN70 captures contain the 24-byte move record followed by eight zero bytes.
 // The native outgoing selector disables the request fold for command19.
 internal static Offline70EconomyMoveRequest ParseMove(byte[] cipher,byte[] keys){if(cipher==null||cipher.Length!=32)throw new InvalidDataException("Move19 cipher bounds");byte[] b=Offline70RoleProtocol.Xtea(cipher,keys,false);for(int i=24;i<32;i++)if(b[i]!=0)throw new InvalidDataException("Move19 trailing padding");if(b[22]>1||b[23]!=0)throw new InvalidDataException("Move19 equipment set or reserved flag");return new Offline70EconomyMoveRequest{SourceList=b[0],SourceSlot=BitConverter.ToUInt16(b,1),SourceItem=BitConverter.ToUInt32(b,3),Quantity=BitConverter.ToUInt32(b,7),TargetList=b[11],TargetSlot=BitConverter.ToUInt16(b,12),TargetItem=BitConverter.ToUInt32(b,14),Tick=BitConverter.ToUInt32(b,18),Alternate=b[22],Reserved=b[23]};}
 internal static byte[] MoveBody(Offline70EconomyMoveRequest r,bool success,byte error){if(r==null)throw new InvalidDataException("Move reply context");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)(success?1:0));if(success){w.Write(r.SourceList);w.Write(r.SourceSlot);w.Write(r.Quantity);w.Write(r.TargetList);w.Write(r.TargetSlot);}else{w.Write(error);w.Write(r.SourceList);w.Write(r.TargetList);}return m.ToArray();}}
 internal static byte[] MoveReply(Offline70EconomyMoveRequest r,bool success,byte[] keys){return Offline70RoleProtocol.Packet(1,19,Offline70RoleProtocol.Xtea(Offline70GoldLoot.Pad(Offline70RoleProtocol.WithDungeonIntegrity(MoveBody(r,success,0x13)),8),keys,true));}
 // Native unequip sends the empty bag position first and the worn item second.
 // Canonicalize only the storage operation; the reply retains the native order.
 internal static Offline70EconomyMoveRequest MoveForStorage(Offline70EconomyMoveRequest r){if(r.SourceItem!=0||r.TargetItem==0)return r;return new Offline70EconomyMoveRequest{SourceList=r.TargetList,SourceSlot=r.TargetSlot,SourceItem=r.TargetItem,Quantity=r.Quantity,TargetList=r.SourceList,TargetSlot=r.SourceSlot,TargetItem=r.SourceItem,Tick=r.Tick,Alternate=r.Alternate,Reserved=r.Reserved};}
 internal static uint ItemData(Offline70EconomyEntry e){Offline70EconomyItemDefinition d=Offline70Economy.Definition(e.ItemId);return d.Kind==6&&e.CreatureKey!=0?e.CreatureKey:d.Kind==3?0:(d.Kind==4||d.Kind==8)&&e.EquipmentSeed>=0?(uint)e.EquipmentSeed:e.Quantity;}
 internal static byte[] InventoryRow(Offline70EconomyEntry e){if(e==null)throw new InvalidDataException("Inventory row context");Offline70EconomyItemDefinition d=Offline70Economy.Definition(e.ItemId);byte[] b=new byte[31];BitConverter.GetBytes(e.Slot).CopyTo(b,0);BitConverter.GetBytes(e.ItemId).CopyTo(b,2);BitConverter.GetBytes(ItemData(e)).CopyTo(b,6);b[10]=Offline70ItemResealFG102.Attribute(e);BitConverter.GetBytes(d.Kind==3?e.Ability:e.Durability).CopyTo(b,11);b[13]=(byte)(e.Sealed?1:0);BitConverter.GetBytes(e.ExpiresUnix).CopyTo(b,22);if(d.Kind!=3)return b;using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(b,0,21);w.Write((uint)30);w.Write(new byte[30]);w.Write(b,21,10);return m.ToArray();}}
 static List<Offline70EconomyEntry> Rows(Offline70EconomyState s,byte list){Offline70Economy.Validate(s);List<Offline70EconomyEntry> rows=new List<Offline70EconomyEntry>();foreach(Offline70EconomyEntry e in s.Inventory)if(e.List==list)rows.Add(e);rows.Sort(delegate(Offline70EconomyEntry a,Offline70EconomyEntry b){return a.Slot.CompareTo(b.Slot);});return rows;}
 // Original 4927A0 restores actor item objects, distinct from visual appearance.
 // Avatar types also carry the length-prefixed 30-byte jewel socket block read at492927.
 internal static byte[] WornRecord(Offline70EconomyState s){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){List<Offline70EconomyEntry> rows=Rows(s,3);w.Write((byte)rows.Count);foreach(Offline70EconomyEntry e in rows){Offline70EconomyItemDefinition d=Offline70Economy.Definition(e.ItemId);w.Write((byte)e.Slot);w.Write(e.ItemId);w.Write(ItemData(e));w.Write(Offline70ItemResealFG102.Attribute(e));w.Write(d.Kind==3?e.Ability:e.Durability);w.Write(UInt32.MaxValue);w.Write((uint)0);w.Write((byte)0);w.Write((ushort)0);if(d.Kind==3){w.Write((uint)30);w.Write(new byte[30]);}w.Write((byte)0);w.Write(e.ExpiresUnix);w.Write((byte)0);w.Write((ushort)0);w.Write((byte)0);w.Write((byte)0);}return m.ToArray();}}
 internal static byte[] AdditionBody(Offline70Role role,Offline70EconomyState s){byte[] b=Offline70RoleProtocol.BatchAdditionBodyFG(role,s.Experience,s.GrowType),worn=WornRecord(s),result=new byte[b.Length+worn.Length-1];Array.Copy(b,0,result,0,101);worn.CopyTo(result,101);Array.Copy(b,102,result,101+worn.Length,b.Length-102);BitConverter.GetBytes(s.NameTagItemFG108).CopyTo(result,101+worn.Length);BitConverter.GetBytes(s.NameTagExpiryFG108).CopyTo(result,105+worn.Length);return Offline70QpShopFG82.Restore(result,s);}
 internal static byte[] AdditionReply(Offline70Role role,Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.EconomyAdditionReply(role,s,keys);}
 internal static byte[] InventoryBody(Offline70EconomyState s,bool restore,byte list){if(list!=0&&list!=1&&list!=2&&list!=7)throw new InvalidDataException("Unverified inventory list body");List<Offline70EconomyEntry> rows=Rows(s,list);using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(list);if(list==2)w.Write(s.CargoSlotsFG129);if(restore&&list==0)w.Write((ushort)0);w.Write((ushort)(rows.Count+(list==0?(s.RevivalCoins>0?2:1):0)));if(list==0){byte[] coin=new byte[31];BitConverter.GetBytes(s.Gold).CopyTo(coin,6);w.Write(coin);if(s.RevivalCoins>0){byte[] revive=new byte[31];BitConverter.GetBytes((ushort)1).CopyTo(revive,0);BitConverter.GetBytes((uint)1).CopyTo(revive,2);BitConverter.GetBytes(s.RevivalCoins).CopyTo(revive,6);w.Write(revive);}}foreach(Offline70EconomyEntry e in rows)w.Write(InventoryRow(e));return m.ToArray();}}
 internal static byte[] InventoryRestoreReply(Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.Packet(0,13,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(InventoryBody(s,true,0),16),keys,13,true));}
 internal static byte[] CargoReplyFG129(Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.BatchPacketFG(0,13,InventoryBody(s,true,2),keys,false);}
 internal static byte[] PetBagReply(Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.Packet(0,13,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(InventoryBody(s,true,7),16),keys,13,true));}
 internal static byte[] AvatarBagReply(Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.Packet(0,13,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(InventoryBody(s,true,1),16),keys,13,true));}
 // Inventory14 is XOR with the established key bytes4..7, matched to the native cipher0 object.
 internal static byte[] UpdatePacket(byte[] plain,byte[] keys){if(keys==null||keys.Length!=334)throw new InvalidDataException("Economy update keys");for(int i=0;i<334;i++)if(keys[i]!=(byte)i)throw new InvalidDataException("Economy fixed update key profile");byte[] body=Offline70GoldLoot.Pad(plain,4);for(int i=0;i<body.Length;i++)body[i]^=keys[4+(i%4)];return Offline70RoleProtocol.Packet(0,14,body);}
 internal static byte[] InventoryUpdateReply(Offline70EconomyState s,byte[] keys){return UpdatePacket(InventoryBody(s,false,0),keys);}
 static bool SameRow(Offline70EconomyEntry a,Offline70EconomyEntry b){return a!=null&&b!=null&&a.List==b.List&&a.Slot==b.Slot&&a.ItemId==b.ItemId&&a.Quantity==b.Quantity&&a.Ability==b.Ability&&a.ExpiresUnix==b.ExpiresUnix&&a.Durability==b.Durability&&a.EquipmentSeed==b.EquipmentSeed&&a.Upgrade==b.Upgrade&&a.ResealCount==b.ResealCount&&a.Sealed==b.Sealed&&a.CreatureKey==b.CreatureKey;}
 internal static byte[] InventoryChangeBody(Offline70EconomyState before,Offline70EconomyState after){Offline70Economy.Validate(before);Offline70Economy.Validate(after);if(before.AccountId!=after.AccountId||before.RoleId!=after.RoleId)throw new InvalidDataException("Inventory delta identity");List<byte[]> delta=new List<byte[]>();if(before.Gold!=after.Gold){byte[] coin=new byte[31];BitConverter.GetBytes(after.Gold).CopyTo(coin,6);delta.Add(coin);}if(before.RevivalCoins!=after.RevivalCoins){byte[] revive=new byte[31];BitConverter.GetBytes((ushort)1).CopyTo(revive,0);BitConverter.GetBytes((uint)1).CopyTo(revive,2);BitConverter.GetBytes(after.RevivalCoins).CopyTo(revive,6);delta.Add(revive);}foreach(Offline70EconomyEntry old in Rows(before,0)){Offline70EconomyEntry current=Offline70Economy.Find(after,0,old.Slot);if(current==null||current.ItemId!=old.ItemId){byte[] gone=new byte[31];BitConverter.GetBytes(old.Slot).CopyTo(gone,0);BitConverter.GetBytes(UInt32.MaxValue).CopyTo(gone,2);delta.Add(gone);}}foreach(Offline70EconomyEntry current in Rows(after,0))if(!SameRow(Offline70Economy.Find(before,0,current.Slot),current))delta.Add(InventoryRow(current));using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)0);w.Write((ushort)delta.Count);foreach(byte[] row in delta)w.Write(row);return m.ToArray();}}
 internal static byte[] WalletReply(Offline70EconomyState s,byte[] keys){byte[] row=new byte[34];row[1]=1;BitConverter.GetBytes(s.Gold).CopyTo(row,9);return UpdatePacket(row,keys);}
 internal static byte[] InventoryChangeReply(Offline70EconomyState before,Offline70EconomyState after,byte[] keys){byte[] body=InventoryChangeBody(before,after);return body.Length==3?null:UpdatePacket(body,keys);}
 internal static byte[] AppearanceRecord(Offline70Role role,Offline70EconomyState s){Offline70Economy.Validate(s);if(role.Id!=s.RoleId||role.Job!=s.Job||role.Level!=s.Level)throw new InvalidDataException("Economy appearance identity");Offline70Role template=new Offline70Role{Id=role.Id,Job=role.Job,Level=1,Name=role.Name,CreatedUtc=role.CreatedUtc};byte[] empty=Offline70RoleProtocol.AppearanceRecord(template);empty[11]=s.GrowType;empty[12]=role.Level;empty=Offline70PetEquipFG97.Appearance(empty,s);empty=Offline70FeedbackCashFG108.Appearance(empty,s);empty[empty.Length-6]=s.StyleOwnedFG129?s.ActiveStyleFG129:(byte)255;List<Offline70EconomyEntry> rows=Rows(s,3);using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(empty,0,16);w.Write((byte)rows.Count);foreach(Offline70EconomyEntry e in rows){w.Write((byte)e.Slot);w.Write(e.ItemId);w.Write((byte)(e.Upgrade<<1));w.Write((uint)0);w.Write((uint)0);}w.Write(empty,17,empty.Length-17);return m.ToArray();}}
 internal static byte[] AppearanceReply(Offline70Role role,Offline70EconomyState s,byte[] keys){return Offline70RoleProtocol.EconomyAppearanceReply(role,s,keys);}
}
partial class Offline70RoleProtocol {internal static byte[] EconomyAppearanceReply(Offline70Role role,Offline70EconomyState s,byte[] keys){byte[] record=Offline70EconomyProtocol.AppearanceRecord(role,s),body=new byte[record.Length+3];body[1]=1;record.CopyTo(body,3);return Packet(0,2,new Blowfish(keys).Encode(Pad(Zlib(body))));}internal static byte[] EconomyAdditionReply(Offline70Role role,Offline70EconomyState s,byte[] keys){return Packet(0,2,new Blowfish(keys).Encode(Pad(Zlib(Offline70EconomyProtocol.AdditionBody(role,s)))));}}
